class ProductoController {
    public function listar() {
        $pdo = new PDO('pgsql:host=localhost;dbname=tienda', 'app', 'secreto');
        $filas = $pdo->query('SELECT nombre, precio FROM productos')->fetchAll();
        echo '<ul>';
        foreach ($filas as $f) {
            echo '<li>' . $f['nombre'] . ' - $' . $f['precio'] . '</li>';
        }
        echo '</ul>';
    }
}

